  assertThatNoException().isThrownBy(() -> taskSlotTable.allocateSlot(-1,jobId1,allocationId,SLOT_TIMEOUT));
  assertThatThrownBy(() -> taskSlotTable.allocateSlot(-1,jobId2,allocationId,SLOT_TIMEOUT)).isInstanceOf(SlotAllocationException.class);
  assertThat(taskSlotTable.isAllocated(1,jobId1,allocationId)).isTrue();
  Iterator<TaskSlot<TaskSlotPayload>> allocatedSlots=taskSlotTable.getAllocatedSlots(jobId1);
  assertThat(allocatedSlots.next().getAllocationId()).isEqualTo(allocationId);
  assertThat(allocatedSlots.hasNext()).isFalse();
}
)

