-    private StreamPhysicalRel visitLookupJoin(
-            final StreamPhysicalLookupJoin lookupJoin, final ImmutableBitSet requireDeterminism) {
-        if (inputInsertOnly(lookupJoin) || requireDeterminism.isEmpty()) {
-            return transmitDeterminismRequirement(lookupJoin, NO_REQUIRED_DETERMINISM);
-        } else {
